CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT DEFAULT 'staff',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS halqas(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,area TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS masajid(id INTEGER PRIMARY KEY AUTOINCREMENT,halqa_id INTEGER,name TEXT NOT NULL,area TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS karkardagi(id INTEGER PRIMARY KEY AUTOINCREMENT,halqa_id INTEGER,masjid_id INTEGER,entry_date TEXT NOT NULL,prayer_meetings INTEGER DEFAULT 0,attendees INTEGER DEFAULT 0,lessons INTEGER DEFAULT 0,visits INTEGER DEFAULT 0,outreach INTEGER DEFAULT 0,notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
